typedef struct {
    int x, y;
} Point;

int cmp_x(const void *a, const void *b) {
    return ((Point*)a)->x - ((Point*)b)->x;
}

int cmp_y(const void *a, const void *b) {
    return ((Point*)a)->y - ((Point*)b)->y;
}

long long modpow(long long a, long long b) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

int main() {
    int N;
    scanf("%d", &N);
    Point pts[N];
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &pts[i].x, &pts[i].y);
    }

    // Sort by x
    qsort(pts, N, sizeof(Point), cmp_x);
    int rankX[N];
    for (int i = 0; i < N; i++) rankX[i] = i; // index = order in x

    // Sort by y
    qsort(pts, N, sizeof(Point), cmp_y);
    int rankY[N];
    for (int i = 0; i < N; i++) rankY[i] = i;

    // Re-sort by x to process in original order but with rank info
    qsort(pts, N, sizeof(Point), cmp_x);

    long long total = 0;
    long long allSubsets = modpow(2, N);

    for (int i = 0; i < N; i++) {
        int left = rankX[i];       // points with x <= this
        int right = N - 1 - left;  // points with x >= this
        int down = rankY[i];
        int up = N - 1 - down;

        long long subsetsWithout = 0;

        // Count subsets that miss at least one side
        // Use inclusion-exclusion on 4 conditions
        long long noLeft = modpow(2, N - left);
        long long noRight = modpow(2, N - right);
        long long noDown = modpow(2, N - down);
        long long noUp = modpow(2, N - up);

        long long noLeftRight = modpow(2, N - left - right);
        long long noLeftDown = modpow(2, N - left - down);
        long long noLeftUp = modpow(2, N - left - up);
        long long noRightDown = modpow(2, N - right - down);
        long long noRightUp = modpow(2, N - right - up);
        long long noDownUp = modpow(2, N - down - up);

        long long noLeftRightDown = modpow(2, N - left - right - down);
        long long noLeftRightUp = modpow(2, N - left - right - up);
        long long noLeftDownUp = modpow(2, N - left - down - up);
        long long noRightDownUp = modpow(2, N - right - down - up);

        long long noAllFour = modpow(2, N - left - right - down - up);

        subsetsWithout = (noLeft + noRight + noDown + noUp) % MOD;
        subsetsWithout = (subsetsWithout - noLeftRight - noLeftDown - noLeftUp - noRightDown - noRightUp - noDownUp) % MOD;
        subsetsWithout = (subsetsWithout + noLeftRightDown + noLeftRightUp + noLeftDownUp + noRightDownUp) % MOD;
        subsetsWithout = (subsetsWithout - noAllFour) % MOD;

        long long subsetsWith = (allSubsets - subsetsWithout) % MOD;
        if (subsetsWith < 0) subsetsWith += MOD;

        total = (total + subsetsWith) % MOD;
    }

    printf("%lld\n", total);
    return 0;
}

