#include <stdio.h>
#include <stdlib.h>

#define MOD 998244353LL

typedef long long ll;

typedef struct {
    int x, y;
} Point;

static int cmpX(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x < q->x) return -1;
    if (p->x > q->x) return 1;
    return 0;
}

static int cmpY(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->y < q->y) return -1;
    if (p->y > q->y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *pts = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &pts[i].x, &pts[i].y);
    }

    /* Compress x-rank and y-rank to permutations 1..N */
    Point *tmp = (Point *)malloc(sizeof(Point) * N);

    for (int i = 0; i < N; i++) tmp[i] = pts[i];
    qsort(tmp, N, sizeof(Point), cmpX);
    /* map by original coordinates using uniqueness */
    /* store x-rank into pts by matching x */
    for (int i = 0; i < N; i++) tmp[i].x = i + 1; /* reuse x field as rank */
    qsort(tmp, N, sizeof(Point), cmpY); /* now sorted by y of original points */

    /* After previous operations are messy, do clean coordinate compression */
    int *xr = (int *)malloc(sizeof(int) * N);
    int *yr = (int *)malloc(sizeof(int) * N);

    Point *sx = (Point *)malloc(sizeof(Point) * N);
    Point *sy = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) sx[i] = sy[i] = pts[i];
    qsort(sx, N, sizeof(Point), cmpX);
    qsort(sy, N, sizeof(Point), cmpY);

    /* Since coordinates are unique, find ranks by binary search on sorted arrays */
    for (int i = 0; i < N; i++) {
        int lo = 0, hi = N - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (sx[mid].x == pts[i].x) {
                xr[i] = mid + 1;
                break;
            } else if (sx[mid].x < pts[i].x) lo = mid + 1;
            else hi = mid - 1;
        }
        lo = 0; hi = N - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (sy[mid].y == pts[i].y) {
                yr[i] = mid + 1;
                break;
            } else if (sy[mid].y < pts[i].y) lo = mid + 1;
            else hi = mid - 1;
        }
    }

    /* pos[x] = y */
    int *pos = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 0; i < N; i++) pos[xr[i]] = yr[i];

    /* powers of 2 */
    ll *pow2 = (ll *)malloc(sizeof(ll) * (N + 1));
    pow2[0] = 1;
    for (int i = 1; i <= N; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;

    /*
      For each point p, count subsets T whose bounding rectangle contains p.
      Let:
      a = # points left of p and below p
      b = # points left of p and above p
      c = # points right of p and below p
      d = # points right of p and above p

      A subset's rectangle contains p iff:
      - subset contains p, or
      - subset has points on both left and right of p, and both below and above p.

      Count second type by choosing non-empty left/right and non-empty below/above consistently.
      Using inclusion-exclusion on quadrants:
      total LR non-empty = (2^(a+b)-1)(2^(c+d)-1)
      among these, require at least one below and at least one above:
      subtract all-below, all-above, add empty.
      result =
      (2^(a+b)-1)(2^(c+d)-1)
      - (2^a-1)(2^c-1)
      - (2^b-1)(2^d-1)

      Then add subsets containing p: 2^(N-1).
    */

    ll ans = 0;
    ll contain_self = pow2[N - 1];

    for (int x = 1; x <= N; x++) {
        int y = pos[x];
        int a = (x - 1 < y - 1) ? (x - 1) : (y - 1); /* temporary wrong? no */
        /* actual quadrant counts from ranks */
        a = 0;
        int b = 0, c = 0, d = 0;
        a = (x - 1) + (y - 1) - ((x - 1) + (y - 1)); /* reset harmlessly */
        a = 0;

        /* Since points form a permutation, counts are determined by scanning impossible in O(N^2).
           Need formulas via inversions? For a fixed point, exact quadrant counts aren't determined
           by ranks alone. So compute using 2D prefix sums.
        */
    }

    /* Build 2D prefix sum on permutation grid */
    int sz = N + 1;
    int *pref = (int *)calloc((size_t)sz * sz, sizeof(int));
    for (int x = 1; x <= N; x++) {
        int y = pos[x];
        pref[x * sz + y] = 1;
    }
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            pref[i * sz + j] += pref[(i - 1) * sz + j] + pref[i * sz + (j - 1)] - pref[(i - 1) * sz + (j - 1)];
        }
    }

    #define RECT(x1,y1,x2,y2) ((x1)>(x2)||(y1)>(y2)?0:(pref[(x2)*sz+(y2)]-pref[((x1)-1)*sz+(y2)]-pref[(x2)*sz+((y1)-1)]+pref[((x1)-1)*sz+((y1)-1)]))

    ans = 0;
    for (int x = 1; x <= N; x++) {
        int y = pos[x];

        int a = RECT(1, 1, x - 1, y - 1);
        int b = RECT(1, y + 1, x - 1, N);
        int c = RECT(x + 1, 1, N, y - 1);
        int d = RECT(x + 1, y + 1, N, y ? N : N);

        ll total_lr = (pow2[a + b] - 1 + MOD) % MOD;
        total_lr = total_lr * ((pow2[c + d] - 1 + MOD) % MOD) % MOD;

        ll all_below = (pow2[a] - 1 + MOD) % MOD;
        all_below = all_below * ((pow2[c] - 1 + MOD) % MOD) % MOD;

        ll all_above = (pow2[b] - 1 + MOD) % MOD;
        all_above = all_above * ((pow2[d] - 1 + MOD) % MOD) % MOD;

        ll add = (contain_self + total_lr - all_below - all_above) % MOD;
        if (add < 0) add += MOD;
        ans += add;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);

    free(pts);
    free(tmp);
    free(xr);
    free(yr);
    free(sx);
    free(sy);
    free(pos);
    free(pow2);
    free(pref);

    return 0;
}

