int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    cin >> N;
    vector<pair<int,int>> pts(N);
    for (int i = 0; i < N; i++) {
        cin >> pts[i].first >> pts[i].second;
    }

    // Precompute powers of 2
    vector<int64> pow2(N+1);
    pow2[0] = 1;
    for (int i = 1; i <= N; i++) {
        pow2[i] = pow2[i-1] * 2 % MOD;
    }

    // Sort by x to get left/right counts
    vector<int> idx_by_x(N);
    iota(idx_by_x.begin(), idx_by_x.end(), 0);
    sort(idx_by_x.begin(), idx_by_x.end(), [&](int a, int b) {
        return pts[a].first < pts[b].first;
    });
    vector<int> rank_x(N);
    for (int i = 0; i < N; i++) rank_x[idx_by_x[i]] = i;

    // Sort by y to get up/down counts
    vector<int> idx_by_y(N);
    iota(idx_by_y.begin(), idx_by_y.end(), 0);
    sort(idx_by_y.begin(), idx_by_y.end(), [&](int a, int b) {
        return pts[a].second < pts[b].second;
    });
    vector<int> rank_y(N);
    for (int i = 0; i < N; i++) rank_y[idx_by_y[i]] = i;

    int64 total_subsets = (pow2[N] - 1 + MOD) % MOD;
    int64 ans = 0;

    for (int i = 0; i < N; i++) {
        int L = rank_x[i];
        int R = N - 1 - rank_x[i];
        int D = rank_y[i];
        int U = N - 1 - rank_y[i];

        // Count points in each quadrant relative to i
        int LD = 0, LU = 0, RD = 0, RU = 0;
        for (int j = 0; j < N; j++) {
            if (i == j) continue;
            bool left = pts[j].first < pts[i].first;
            bool right = pts[j].first > pts[i].first;
            bool down = pts[j].second < pts[i].second;
            bool up = pts[j].second > pts[i].second;
            if (left && down) LD++;
            if (left && up) LU++;
            if (right && down) RD++;
            if (right && up) RU++;
        }

        int64 outside = 0;
        outside = (outside + (pow2[L] - 1 + MOD) % MOD) % MOD;
        outside = (outside + (pow2[R] - 1 + MOD) % MOD) % MOD;
        outside = (outside + (pow2[D] - 1 + MOD) % MOD) % MOD;
        outside = (outside + (pow2[U] - 1 + MOD) % MOD) % MOD;

        outside = (outside - (pow2[LD] - 1 + MOD) % MOD + MOD) % MOD;
        outside = (outside - (pow2[LU] - 1 + MOD) % MOD + MOD) % MOD;
        outside = (outside - (pow2[RD] - 1 + MOD) % MOD + MOD) % MOD;
        outside = (outside - (pow2[RU] - 1 + MOD) % MOD + MOD) % MOD;

        int64 inside = (total_subsets - outside + MOD) % MOD;
        ans = (ans + inside) % MOD;
    }

    cout << ans % MOD << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<int,int>> p(N);
    for (int i = 0; i < N; ++i) cin >> p[i].first >> p[i].second;

    // Compress x-rank
    vector<pair<int,int>> xs;
    for (int i = 0; i < N; ++i) xs.push_back({p[i].first, i});
    sort(xs.begin(), xs.end());
    vector<int> xr(N);
    for (int i = 0; i < N; ++i) xr[xs[i].second] = i + 1;

    // Compress y-rank
    vector<pair<int,int>> ys;
    for (int i = 0; i < N; ++i) ys.push_back({p[i].second, i});
    sort(ys.begin(), ys.end());
    vector<int> yr(N);
    for (int i = 0; i < N; ++i) yr[ys[i].second] = i + 1;

    // Order points by y-rank; a[i] = x-rank of i-th lowest y
    vector<int> a(N + 1);
    for (int i = 0; i < N; ++i) {
        a[yr[i]] = xr[i];
    }

    // powers of 2
    vector<long long> pw(N + 1, 1);
    for (int i = 1; i <= N; ++i) pw[i] = pw[i - 1] * 2 % MOD;

    // For each point p, count subsets T for which rectangle(T) contains p.
    // Then sum over points.
    //
    // Let point p be at (x0, y0) in rank coordinates.
    // A subset T contributes to p iff:
    //   minX(T) <= x0 <= maxX(T), and minY(T) <= y0 <= maxY(T).
    //
    // Equivalently, T is not entirely in any of the four open quadrants
    // relative to p, and must be non-empty.
    //
    // More directly, choose y-interval [l..r] with l <= y0 <= r.
    // Among points with y in [l..r], T must contain at least one point with x <= x0
    // and at least one point with x >= x0.
    //
    // Since x's are distinct and p itself lies in every such interval containing y0,
    // this becomes:
    //   number of non-empty subsets of interval points whose x-range contains x0
    // = 2^k - 2^L - 2^R + 1
    // where k = r-l+1,
    //       L = #points in interval with x < x0,
    //       R = #points in interval with x > x0.
    //
    // We compute this for each fixed center y0 by expanding intervals [l..r].
    //
    // O(N^2).

    long long ans = 0;

    for (int y0 = 1; y0 <= N; ++y0) {
        int x0 = a[y0];

        // Fix top boundary r, expand downward l.
        // Maintain counts of x < x0 and x > x0 in current interval.
        int leftCnt = 0, rightCnt = 0;

        for (int r = y0; r <= N; ++r) {
            if (r > y0) {
                if (a[r] < x0) ++leftCnt;
                else ++rightCnt;
            }

            int curL = leftCnt;
            int curR = rightCnt;
            int len = r - y0 + 1;

            // interval [y0..r]
            long long add = (pw[len] - pw[curL] - pw[curR] + 1) % MOD;
            if (add < 0) add += MOD;
            ans += add;
            if (ans >= MOD) ans -= MOD;

            // extend lower boundary upward? We instead enumerate all l by a second pass below.
        }

        // Intervals with l < y0 need both sides around y0.
        // Enumerate l downward, and for each l combine with all r >= y0.
        // Simpler O(N^2) per point would be too much, so instead do all intervals [l..r]
        // containing y0 by fixing l and extending r, total O(N^2) over all y0 is still okay
        // only if N is small; but we need true O(N^2).
    }

    // The above only counted intervals with l = y0, so we need a different O(N^2) method.

    // Recompute using contribution by choosing vertical span [l..r] and counting points inside it.
    // For a fixed span [l..r], let k = r-l+1.
    // A point with x-rank x is contained in rectangle(T) for exactly
    //   2^k - 2^{cntLeft} - 2^{cntRight} + 1
    // subsets T of these k points,
    // where cntLeft = #points in span with x < x,
    //       cntRight = #points in span with x > x.
    //
    // If we list the x-ranks in the span in sorted order, for the t-th smallest x:
    //   cntLeft = t-1, cntRight = k-t.
    // So total contribution of this span is:
    //   sum_{t=1..k} (2^k - 2^{t-1} - 2^{k-t} + 1)
    // = k*2^k - 2*(2^k - 1) + k
    // = (k-2)*2^k + k + 2.
    //
    // Beautifully depends only on k.
    //
    // Therefore answer is sum over all y-spans [l..r] of g(k), k=r-l+1.
    // Number of spans of length k is N-k+1.
    //
    // Final:
    // ans = sum_{k=1..N} (N-k+1) * ((k-2)*2^k + k + 2)

    ans = 0;
    for (int k = 1; k <= N; ++k) {
        long long g = ((long long)(k - 2) * pw[k] + k + 2) % MOD;
        if (g < 0) g += MOD;
        ans = (ans + (long long)(N - k + 1) * g) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

