import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    static class Fenwick {
        int n;
        int[] bit;
        Fenwick(int n) {
            this.n = n;
            bit = new int[n + 1];
        }
        void add(int idx, int delta) {
            for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
        }
        int sum(int idx) {
            int res = 0;
            for (; idx > 0; idx -= idx & -idx) res += bit[idx];
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        Point[] pts = new Point[N];
        int[] xs = new int[N];
        int[] ys = new int[N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            pts[i] = new Point(x, y);
            xs[i] = x; ys[i] = y;
        }

        // compress coordinates
        Arrays.sort(xs);
        Arrays.sort(ys);
        Map<Integer, Integer> xmap = new HashMap<>();
        Map<Integer, Integer> ymap = new HashMap<>();
        for (int i = 0; i < N; i++) {
            xmap.put(xs[i], i + 1);
            ymap.put(ys[i], i + 1);
        }
        for (Point p : pts) {
            p.x = xmap.get(p.x);
            p.y = ymap.get(p.y);
        }

        // Precompute powers of 2
        long[] pow2 = new long[N + 1];
        pow2[0] = 1;
        for (int i = 1; i <= N; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;

        long totalSubsets = (pow2[N] - 1 + MOD) % MOD;

        // L and R counts
        Arrays.sort(pts, Comparator.comparingInt(p -> p.x));
        int[] L = new int[N];
        int[] R = new int[N];
        for (int i = 0; i < N; i++) {
            L[i] = i;
            R[i] = N - 1 - i;
        }

        // D and U counts by y
        Integer[] idxByY = new Integer[N];
        for (int i = 0; i < N; i++) idxByY[i] = i;
        Arrays.sort(idxByY, Comparator.comparingInt(i -> pts[i].y));
        int[] D = new int[N];
        int[] U = new int[N];
        for (int pos = 0; pos < N; pos++) {
            int i = idxByY[pos];
            D[i] = pos;
            U[i] = N - 1 - pos;
        }

        // Quadrant counts using Fenwick tree
        Fenwick bit = new Fenwick(N);
        int[] QLD = new int[N];
        for (int i = 0; i < N; i++) {
            int y = pts[i].y;
            QLD[i] = bit.sum(y - 1);
            bit.add(y, 1);
        }

        bit = new Fenwick(N);
        int[] QLU = new int[N];
        for (int i = 0; i < N; i++) {
            int y = pts[i].y;
            QLU[i] = bit.sum(N) - bit.sum(y);
            bit.add(y, 1);
        }

        // reverse order for right quadrants
        bit = new Fenwick(N);
        int[] QRD = new int[N];
        for (int i = N - 1; i >= 0; i--) {
            int y = pts[i].y;
            QRD[i] = bit.sum(y - 1);
            bit.add(y, 1);
        }

        bit = new Fenwick(N);
        int[] QRU = new int[N];
        for (int i = N - 1; i >= 0; i--) {
            int y = pts[i].y;
            QRU[i] = bit.sum(N) - bit.sum(y);
            bit.add(y, 1);
        }

        long ans = 0;
        for (int i = 0; i < N; i++) {
            long excl = 0;
            excl = (excl + (pow2[L[i]] - 1)) % MOD;
            excl = (excl + (pow2[R[i]] - 1)) % MOD;
            excl = (excl + (pow2[D[i]] - 1)) % MOD;
            excl = (excl + (pow2[U[i]] - 1)) % MOD;

            excl = (excl - (pow2[QLD[i]] - 1) + MOD) % MOD;
            excl = (excl - (pow2[QLU[i]] - 1) + MOD) % MOD;
            excl = (excl - (pow2[QRD[i]] - 1) + MOD) % MOD;
            excl = (excl - (pow2[QRU[i]] - 1) + MOD) % MOD;

            long incl = (totalSubsets - excl + MOD) % MOD;
            ans = (ans + incl) % MOD;
        }

        System.out.println(ans);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 998244353;
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] X = new int[N], Y = new int[N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            X[i] = Integer.parseInt(st.nextToken());
            Y[i] = Integer.parseInt(st.nextToken());
        }
        int[] rx = X.clone(), ry = Y.clone();
        Arrays.sort(rx); Arrays.sort(ry);
        int[] xi = new int[N], yi = new int[N];
        for (int i = 0; i < N; i++) {
            xi[i] = Arrays.binarySearch(rx, X[i]);
            yi[i] = Arrays.binarySearch(ry, Y[i]);
        }
        long[] pw = new long[N+1];
        pw[0] = 1;
        for (int i = 1; i <= N; i++) pw[i] = pw[i-1]*2%MOD;
        // For quadrant counts: need # points in each quadrant relative to p
        // Use 2D prefix sum on (xi, yi) grid
        int[][] grid = new int[N][N];
        for (int i = 0; i < N; i++) grid[xi[i]][yi[i]] = 1;
        // prefix[i][j] = # points with xi <= i and yi <= j
        long[][] pre = new long[N+1][N+1];
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                pre[i+1][j+1] = grid[i][j] + pre[i][j+1] + pre[i+1][j] - pre[i][j];
        long ans = 0;
        for (int p = 0; p < N; p++) {
            int px = xi[p], py = yi[p];
            long r = N-1-px, l = px, u = N-1-py, d = py;
            // quadrants: ru = x>px and y>py
            long ru = query(pre, px+1, N-1, py+1, N-1);
            long rd = query(pre, px+1, N-1, 0, py-1);
            long lu = query(pre, 0, px-1, py+1, N-1);
            long ld = query(pre, 0, px-1, 0, py-1);
            long contrib = (pw[N] - 1 - pw[(int)r] - pw[(int)l] - pw[(int)u] - pw[(int)d]
                + pw[(int)ru] + pw[(int)rd] + pw[(int)lu] + pw[(int)ld]) % MOD;
            ans = (ans + contrib) % MOD;
        }
        System.out.println((ans % MOD + MOD) % MOD);
    }
    static long query(long[][] pre, int x1, int x2, int y1, int y2) {
        if (x1 > x2 || y1 > y2) return 0;
        return pre[x2+1][y2+1] - pre[x1][y2+1] - pre[x2+1][y1] + pre[x1][y1];
    }
}

import java.io.*;
import java.util.*;

/*
We need sum over all non-empty subsets T of S:
f(T) = number of points in the smallest axis-aligned rectangle containing T.

Points have distinct x and distinct y.

Key counting:
For each point p, count number of non-empty subsets T such that p lies inside
the bounding rectangle of T. Then answer is sum of these counts over all p.

Fix p. Let:
A = points left of p and below p
B = points left of p and above p
C = points right of p and below p
D = points right of p and above p

A subset T has rectangle containing p iff either:
- p in T, or
- T contains at least one point on each side in x and y around p:
  (left and right) and (below and above)

Equivalently for subsets not containing p:
choose non-empty subset from left side (A∪B),
choose non-empty subset from right side (C∪D),
with at least one below (A∪C) and at least one above (B∪D).

Number of such subsets:
all choices from 4 quadrants satisfying:
(a+b)>=1, (c+d)>=1, (a+c)>=1, (b+d)>=1
where a,b,c,d indicate chosen subset from corresponding quadrant, possibly empty but
not all empty in a quadrant count sense. Since each quadrant has multiple points,
we count by powers of 2.

Let xa=2^|A|, xb=2^|B|, xc=2^|C|, xd=2^|D|.
Number of quadrant-subset choices satisfying conditions is:
total over left/right non-empty:
(xa*xb - 1)(xc*xd - 1)
minus those with no below: b>=1,d>=1 => (xb-1)(xd-1)
minus those with no above: a>=1,c>=1 => (xa-1)(xc-1)

This already ensures left/right non-empty, so valid.
Then add subsets containing p: 2^(N-1).

Thus contribution of p:
2^(N-1) + (2^{|A|+|B|}-1)(2^{|C|+|D|}-1) - (2^{|B|}-1)(2^{|D|}-1) - (2^{|A|}-1)(2^{|C|}-1)

Need sums of counts by quadrants for every point.

After compressing x-order and y-order to permutations:
for each point p at (xRank=i, yRank=j):
|A| = count of points with x<i and y<j
|B| = (i-1) - |A|
|C| = (j-1) - |A|
Actually C is right & below, so among below points total j-1, subtract A.
|D| = N -1 -A-B-C

We need A for each point = number of earlier x with smaller y.
This is inversion-prefix count via Fenwick.
Similarly can derive all others from ranks.

Complexity O(N log N).
*/

public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Fenwick {
        int n;
        int[] bit;
        Fenwick(int n) {
            this.n = n;
            bit = new int[n + 2];
        }
        void add(int idx, int delta) {
            for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
        }
        int sum(int idx) {
            int res = 0;
            for (; idx > 0; idx -= idx & -idx) res += bit[idx];
            return res;
        }
    }

    static class Point {
        int x, y, yr;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        Point[] pts = new Point[N];
        int[] ys = new int[N];
        for (int i = 0; i < N; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            pts[i] = new Point(x, y);
            ys[i] = y;
        }

        Arrays.sort(ys);
        HashMap<Integer, Integer> yRank = new HashMap<>(N * 2);
        for (int i = 0; i < N; i++) yRank.put(ys[i], i + 1);
        for (Point p : pts) p.yr = yRank.get(p.y);

        Arrays.sort(pts, Comparator.comparingInt(a -> a.x));

        long[] pow2 = new long[N + 1];
        pow2[0] = 1;
        for (int i = 1; i <= N; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;

        Fenwick fw = new Fenwick(N);
        long ans = 0;
        long withP = pow2[N - 1];

        for (int i = 0; i < N; i++) {
            int xRank = i + 1;
            int yR = pts[i].yr;

            int A = fw.sum(yR - 1);
            int B = (xRank - 1) - A;
            int C = (yR - 1) - A;
            int D = N - 1 - A - B - C;

            long leftNonEmpty = (pow2[A + B] - 1 + MOD) % MOD;
            long rightNonEmpty = (pow2[C + D] - 1 + MOD) % MOD;
            long noBelow = ((pow2[B] - 1 + MOD) % MOD) * ((pow2[D] - 1 + MOD) % MOD) % MOD;
            long noAbove = ((pow2[A] - 1 + MOD) % MOD) * ((pow2[C] - 1 + MOD) % MOD) % MOD;

            long withoutP = (leftNonEmpty * rightNonEmpty - noBelow - noAbove) % MOD;
            if (withoutP < 0) withoutP += MOD;
            if (withoutP < 0) withoutP += MOD;

            ans += withP + withoutP;
            ans %= MOD;

            fw.add(yR, 1);
        }

        System.out.println(ans % MOD);
    }
}
